INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6801, '1 Samuel 4:4', '1 Samuel', 4, 4, '&nbsp;نو هغوئ سيلا ته پېغام وړُونکى ولېږل او د ربُ الافواج د لوظ صندوق يې واپس راوړو، چې د وزرو والا د مخلوق په مينځ کښې په تخت ناست دے. او د عيلى دوه زامن حُفنى او فينحاس د لوظ صندوق سره راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6802, '1 Samuel 4:5', '1 Samuel', 4, 5, '&nbsp;کله چې د لوظ صندوق راورسېدو، نو بنى اِسرائيلو د خوشحالۍ نه دومره لويه چغه ووهله چې زمکه وخوځېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6803, '1 Samuel 4:6', '1 Samuel', 4, 6, '&nbsp;فلستيانو دا چغه واورېدله او وې وئيل، ”د عبرانيانو په کېمپ کښې دا چغې واورئ. د دې څۀ مطلب دے؟“ کله چې هغوئ ته پته ولګېده چې د مالِک خُدائ د لوظ صندوق د عبرانيانو کېمپ ته رارسېدلے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6804, '1 Samuel 4:7', '1 Samuel', 4, 7, '&nbsp;هغوئ ويرېدل او وې وئيل، ”د هغوئ کېمپ ته خُدائ راغلے دے. مونږ غرق شُو. په مونږ باندې هيڅکله مخکښې داسې څۀ نۀ دى شوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6805, '1 Samuel 4:8', '1 Samuel', 4, 8, '&nbsp;زمونږ مدد وکړه، مونږ به د هغه طاقتورو معبودانو نه څوک بچ کړى؟ دا هغه معبودان دى چا چې په صحرا کښې مِصريان هلاک کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6806, '1 Samuel 4:9', '1 Samuel', 4, 9, '&nbsp;فلستيانو، تکړه شئ. د سړو په شان وجنګېږئ، ګنې مونږ به د عبرانيانو غلامان شُو، لکه څنګه چې هغوئ زمونږ غلامان وُو. نو د سړو په شان جنګ وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6807, '1 Samuel 4:10', '1 Samuel', 4, 10, '&nbsp;فلستيان سخت وجنګېدل او بنى اِسرائيلو له يې شکست ورکړو، چې هغوئ په منډه خپلو کورونو ته لاړل. دا يو لوئ قتلِ عام وو. او دېرش زره بنى اِسرائيلى فوجيان ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6808, '1 Samuel 4:11', '1 Samuel', 4, 11, '&nbsp;د خُدائ پاک د لوظ صندوق قبضه کړے شو او د عيلى دواړه زامن، حُفنى او فينحاس ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6809, '1 Samuel 4:12', '1 Samuel', 4, 12, '&nbsp;د بنيامين قبيلې يو سړى د جنګ مېدان نه تر سيلا پورې منډه ووهله او هم په هغه ورځ ورسېدو. د خپل تکليف ښودلو دپاره هغۀ خپلې جامې شلولې وې او په سر باندې يې خاورې اچولې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6810, '1 Samuel 4:13', '1 Samuel', 4, 13, '&nbsp;عيلى د لوظ صندوق په حقله ډېر پرېشانه وو، هغه د لارې په غاړه په يوه کُرسۍ باندې ناست وو او انتظار يې کولو. هغه سړى دا خبر په ټول ښار کښې خور کړو او هر يو کس د يرې نه وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6811, '1 Samuel 4:14', '1 Samuel', 4, 14, '&nbsp;عيلى شور واورېدو او تپوس يې وکړو، ”دا شور د څۀ شى دے؟“ هغه سړے عيلى له په منډه لاړو او هغه يې خبر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6812, '1 Samuel 4:15', '1 Samuel', 4, 15, '&nbsp;عيلى اوس د دوه کم سلو کالو وو او بېخى ړوند وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6813, '1 Samuel 4:16', '1 Samuel', 4, 16, '&nbsp;سړى ورته ووئيل، ”زۀ نن د جنګ نه راتښتېدلے يم.“ عيلى ترې نه تپوس وکړو، ”زما زويه، څۀ شوى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6814, '1 Samuel 4:17', '1 Samuel', 4, 17, '&nbsp;هغه پېغام وړُونکى ورته په جواب کښې ووئيل، ”بنى اِسرائيليان د فلستيانو نه وتښتېدل، دا زمونږ دپاره ډېر خراب شکست وو، د دې نه علاوه، ستا زامن، حُفنى او فينحاس هم ووژلے شول او د خُدائ پاک د لوظ صندوق قبضه کړے شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6815, '1 Samuel 4:18', '1 Samuel', 4, 18, '&nbsp;کله چې هغه سړى د لوظ د صندوق ذِکر وکړو، نو عيلى د دروازې سره د کُرسۍ نه په شا وغورزېدو. هغه ډېر بوډا او غټ وو او په غورزېدو سره يې څټ مات شو او مړ شو. هغه څلوېښت کاله د بنى اِسرائيلو قاضى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6816, '1 Samuel 4:19', '1 Samuel', 4, 19, '&nbsp;د عيلى اِنږور، د فينحاس ښځه اُميدواره وه او تقريباً دا د هغې د بچى د پېدا کېدو وخت وو. کله چې هغه خبر شوه چې د خُدائ پاک د لوظ صندوق قبضه کړے شوے دے او سخر او خاوند يې مړۀ شوى دى، نو ناڅاپه په هغې باندې د ماشوم د پېدا کېدو سخت درد راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6817, '1 Samuel 4:20', '1 Samuel', 4, 20, '&nbsp;او کله چې هغه د مرګ په حالت کښې وه، نو چې کومو ښځو د هغې مدد کولو هغوئ ورته ووئيل چې، ”تکړه شه، ستا زوئ پېدا شوے دے.“ خو هغې هيڅ توجو ورنۀ کړه او نۀ يې جواب ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6818, '1 Samuel 4:21', '1 Samuel', 4, 21, '&nbsp;هغې په ماشوم باندې يکبود نوم کېښودو او وې وئيل چې، ”د خُدائ پاک جلال د بنى اِسرائيلو نه تلے دے.“ دا ځکه چې د لوظ صندوق قبضه شوے وو او د هغې سخر او خاوند مړۀ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6819, '1 Samuel 4:22', '1 Samuel', 4, 22, '&nbsp;هغې ووئيل، ”د خُدائ پاک جلال د بنى اِسرائيلو نه تلے دے، ځکه چې د خُدائ پاک د لوظ صندوق قبضه کړے شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6820, '1 Samuel 5:1', '1 Samuel', 5, 1, '&nbsp;کله چې فلستيانو د لوظ صندوق قبضه کړو نو هغوئ د اِبن‌عزر نه خپل ښار اشدود ته راوړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6821, '1 Samuel 5:2', '1 Samuel', 5, 2, '&nbsp;د خپل معبود دجون کور ته يې يوړو او د هغۀ د بُت په خوا کښې يې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6822, '1 Samuel 5:3', '1 Samuel', 5, 3, '&nbsp;سحر وختى د اشدود خلقو وليدل چې د دجون بُت د مالِک خُدائ د لوظ صندوق په مخکښې پړمخې په زمکه غورزېدلے دے. نو هغوئ را اوچت کړو او واپس يې په خپل ځائ کښې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6823, '1 Samuel 5:4', '1 Samuel', 5, 4, '&nbsp;په ورپسې سحر وختى هغوئ وليدل چې بُت بيا د مالِک خُدائ د لوظ صندوق په مخکښې پړمخې په زمکه غورزېدلے وو. دې ځل يې سر او دواړه لاسونه مات شوى وُو او د دروازې د درشل سره پراتۀ وُو، صِرف ډانچه يې پاتې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6824, '1 Samuel 5:5', '1 Samuel', 5, 5, '&nbsp;نو ځکه تر نن پورې د دجون اِمامان او د هغۀ ټول عبادت کوونکى په اشدود کښې د دجون په درشل باندې قدم نۀ ږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6825, '1 Samuel 5:6', '1 Samuel', 5, 6, '&nbsp;مالِک خُدائ د اشدود خلقو له سخته سزا ورکړه او په هغوئ او د ګېرچاپېره علاقې په خلقو باندې يې د پړسوب مرض راوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6826, '1 Samuel 5:7', '1 Samuel', 5, 7, '&nbsp;کله چې هغوئ وکتل چې دا څۀ کيږى نو وې وئيل، ”د بنى اِسرائيلو خُدائ پاک مونږ او زمونږ معبود دجون له سزا راکوى. مونږ د لوظ صندوق نور دلته نۀ شُو پرېښودلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6827, '1 Samuel 5:8', '1 Samuel', 5, 8, '&nbsp;نو هغوئ پېغام وړُونکى ولېږل او فلستى پينځۀ واړه بادشاهان يې راغونډ کړل او تپوس يې ترې نه وکړو، ”د بنى اِسرائيلو د خُدائ پاک د لوظ صندوق سره مو څۀ چل وکړُو؟“ هغوئ ورته په جواب کښې ووئيل، ”دا جات ته يوسئ.“ نو هغوئ دا د فلستى بل ښار جات ته يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6828, '1 Samuel 5:9', '1 Samuel', 5, 9, '&nbsp;کله چې هغه هلته ورسېدو، مالِک خُدائ هغه ښار له هم سزا ورکړه او په يوه لويه وارخطايۍ يې آخته کړو. هغۀ هغوئ له داسې سزا ورکړه چې په لويو او وړو ټولو باندې د پړسوب مرض راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6829, '1 Samuel 5:10', '1 Samuel', 5, 10, '&nbsp;نو هغوئ د لوظ صندوق يو بل فلستى ښار عقرون ته ولېږلو، خو چې هغه هلته ورسېدو، نو خلقو چغې کړې او وې وئيل، ”هغوئ د بنى اِسرائيلو د خُدائ پاک د لوظ صندوق دلته راوړو، د دې دپاره چې مونږ ټول ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6830, '1 Samuel 5:11', '1 Samuel', 5, 11, '&nbsp;نو هغوئ بيا د فلستيه ټول بادشاهان راوغوښتل او ورته يې ووئيل، ”د بنى اِسرائيلو د لوظ صندوق واپس خپل ځائ ته ولېږئ، نو داسې به دا مونږ او زمونږ خاندان ونۀ وژنى.“ ټول ښار په وارخطايۍ آخته وو ځکه چې خُدائ پاک هغوئ له ډېره سخته سزا ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6831, '1 Samuel 5:12', '1 Samuel', 5, 12, '&nbsp;چې څوک لا مړۀ شوى نۀ وُو نو په هغوئ باندې د پړسوب مرض راغلو، او خلقو خپلو معبودانو ته د مدد دپاره چغې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6832, '1 Samuel 6:1', '1 Samuel', 6, 1, '&nbsp;نو چې د مالِک خُدائ د لوظ صندوق د فلستيانو په مُلک کښې اووۀ مياشتې وشوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6833, '1 Samuel 6:2', '1 Samuel', 6, 2, '&nbsp;نو خلقو اِمامان او جادوګران راوغوښتل او تپوس يې ترې نه وکړو، ”مونږ د مالِک خُدائ د لوظ صندوق سره څۀ چل وکړُو؟ مونږ ته ووايئ چې دا څنګه واپس خپل ځائ ته يوسو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6834, '1 Samuel 6:3', '1 Samuel', 6, 3, '&nbsp;هغوئ جواب ورکړو، ”کۀ تاسو د بنى اِسرائيلو د خُدائ پاک د لوظ صندوق لېږئ، نو تاسو به د دې سره خامخا د خپلې ګناه د تاوان د نذرانې په بدل کښې يوه تُحفه هغۀ له لېږئ. د لوظ صندوق به د تُحفې نه بغېر واپس نۀ ځى. نو داسې به تاسو روغ جوړ شئ او تاسو ته به پته ولګى چې هغۀ تاسو له سزا ولې درکوله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6835, '1 Samuel 6:4', '1 Samuel', 6, 4, '&nbsp;خلقو تپوس وکړو، ”مونږ هغۀ له د ګناه د تاوان په نذرانه کښې څۀ ولېږُو؟“ هغوئ ورته په جواب کښې ووئيل، ”پينځۀ د سرو زرو د پړسوب د دانو او پينځۀ د سرو زرو د مږو نمونې، د فلستيانو بادشاهانو د شمېر په مطابق يوه يوه ورولېږئ ځکه هم دغه وبا په تاسو ټولو او په پينځو بادشاهانو باندې راغلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6836, '1 Samuel 6:5', '1 Samuel', 6, 5, '&nbsp;تاسو د دې دانو او مږو نمونې جوړې کړئ چې ستاسو مُلک تباه کوى او تاسو به خامخا د بنى اِسرائيلو د خُدائ پاک درناوے کوئ. کېدے شى چې هغه تاسو له، ستاسو معبودانو او ستاسو مُلک له سزا درکول بند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6837, '1 Samuel 6:6', '1 Samuel', 6, 6, '&nbsp;تاسو ضديان ولې جوړېږئ څنګه چې فِرعون او مِصريان وُو؟ هغه مۀ هېروئ چې خُدائ پاک هغوئ له څومره سخته سزا ورکړه، تر دې وخت پورې چې هغوئ بنى اِسرائيليان پرېښودل چې د مِصر نه لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6838, '1 Samuel 6:7', '1 Samuel', 6, 7, '&nbsp;نو يوه نوې ګاډۍ او دوه غواګانې تيارې کړئ چې اوس اوس يې بچى شوى وى او چې هيڅکله جغ ورپورې نۀ وى تړلے شوے، ګاډۍ په دې غواګانو پورې وتړئ او سخى يې واپس ديرې ته وشړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6839, '1 Samuel 6:8', '1 Samuel', 6, 8, '&nbsp;د مالِک خُدائ د لوظ صندوق واخلئ، په ګاډۍ کښې يې کېږدئ او د دې په خوا کښې په يو صندوق کښې د سرو زرو هغه نمونې کېږدئ کومې چې ستاسو د ګناه د تاوان د نذرانې په بدل کښې په تُحفه کښې هغۀ له لېږئ. ګاډۍ په خپله مخه روانه کړئ او پرېږدئ چې په خپله لاړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6840, '1 Samuel 6:9', '1 Samuel', 6, 9, '&nbsp;چې ګاډۍ روانه وى نو ورته ګورئ، کۀ دا د بيت‌شمس ښار طرف ته لاړه شى، نو د دې مطلب دا دے چې دا د بنى اِسرائيلو خُدائ پاک دے چې هغۀ په مونږ باندې دا سخت افت راوستے دے. خو کۀ داسې نۀ وى، نو بيا به مونږ ته پته ولګى چې هغۀ وبا نۀ وه راوستې، او په خپله داسې وشول.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6841, '1 Samuel 6:10', '1 Samuel', 6, 10, '&nbsp;هغوئ ته چې څۀ وئيلے شوى وُو نو هم هغسې يې وکړل يعنې، هغوئ دوه غواګانې بوتلې او يوه ګاډۍ يې ورپورې وتړله او سخى يې په ديره کښې وتړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6842, '1 Samuel 6:11', '1 Samuel', 6, 11, '&nbsp;هغوئ د لوظ صندوق په ګاډۍ کښې کېښودو، ورسره هغه صندوق يې هم کېښودو چې د سرو زرو د مږو او دانو نمونې په کښې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6843, '1 Samuel 6:12', '1 Samuel', 6, 12, '&nbsp;غواګانې د بيت‌شمس په لاره روانې شوې او سيدها هغه طرف ته لاړې او د لارې نه نۀ اوړېدلې. چې دا روانې وې نو رمباړې يې وهلې. هغه پينځۀ فلستى بادشاهان د بيت‌شمس د حد پولې پورې ورپسې روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6844, '1 Samuel 6:13', '1 Samuel', 6, 13, '&nbsp;د بيت‌شمس خلقو په مېدان کښې د غنمو لَو کولو، چې ناڅاپه هغوئ وکتل نو د لوظ صندوق يې وليدو. هغوئ د دې په ليدو ډېر خوشحاله شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6845, '1 Samuel 6:16', '1 Samuel', 6, 16, '&nbsp;پينځو فلستى بادشاهانو دا هر څۀ وليدل او بيا هم په هغه ورځ واپس عقرون ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6846, '1 Samuel 6:17', '1 Samuel', 6, 17, '&nbsp;فلستيانو پينځۀ د سرو زرو دانو نمونې مالِک خُدائ ته د هغوئ د ګناه د تاوان د نذرانې دپاره ولېږلې، د اشدود، غزه، اسقلون، جات او عقرون د ښارونو دپاره يوه يوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6847, '1 Samuel 6:18', '1 Samuel', 6, 18, '&nbsp;هغوئ د سرو زرو مږې هم ولېږلې، د هغه ښارونو دپاره يوه يوه چې په کومو باندې هغه پينځو فلستى بادشاهانو حکومت کولو او ورسره د پَخو دېوالونو ښارونو او د کچه دېوالونو کلو ته يې هم ولېږل. د بيت‌شمس د يشوَع په پټى کښې هغه لوئ ګټ تر اوسه پورې شته چې په کوم باندې هغوئ د مالِک خُدائ د لوظ صندوق اېښے وو، دا د هغې ګواهى ده چې څۀ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6848, '1 Samuel 6:19', '1 Samuel', 6, 19, '&nbsp;مالِک خُدائ د بيت‌شمس اويا سړى ووژل ځکه چې هغوئ د لوظ صندوق ته دننه کتلى وُو. او خلقو ماتم وکړو ځکه چې مالِک خُدائ په هغوئ دومره لويه تباهى راوستلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6849, '1 Samuel 6:20', '1 Samuel', 6, 20, '&nbsp;نو د بيت‌شمس خلقو ووئيل، ”د مالِک خُدائ، د دې مقدس خُدائ پاک په وړاندې څوک ودرېدے شى، مونږ هغه چرته ولېږُو چې زمونږ نه لرې شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6850, '1 Samuel 6:21', '1 Samuel', 6, 21, '&nbsp;هغوئ د قِريَت‌يعريم خلقو ته پېغام وړُونکى ولېږل چې ورته ووائى، ”فلستيانو د مالِک خُدائ د لوظ صندوق واپس کړے دے. راشئ او يو يې سئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6851, '1 Samuel 7:1', '1 Samuel', 7, 1, '&nbsp;نو د قِريَت‌يعريم خلق راغلل او د مالِک خُدائ د لوظ صندوق يې د ابينداب نومې سړى کور ته يوړو، چې هغه په غر کښې اوسېدو. هغوئ د ابينداب زوئ اِلى‌عزر د دې مشر مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6852, '1 Samuel 7:2', '1 Samuel', 7, 2, '&nbsp;د مالِک خُدائ د لوظ صندوق ډېره موده تقريباً تر شلو کالو پورې په قِريَت‌يعريم کښې ايسار وو. په دې وخت کښې ټولو بنى اِسرائيلو مالِک خُدائ ته د مدد دپاره وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6853, '1 Samuel 7:3', '1 Samuel', 7, 3, '&nbsp;سموئيل بنى اِسرائيلو ته وفرمائيل، ”کۀ تاسو د زړۀ د اخلاصه مالِک خُدائ ته راواوړئ، نو تاسو به خامخا د ټولو پردو معبودانو او عستارات بُتانو نه ځان خلاصوئ. خپل ځانونه مالِک خُدائ ته حواله کړئ او صِرف د هغۀ عبادت کوئ او هغه به تاسو د فلستيانو د زور نه خلاص کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6854, '1 Samuel 7:4', '1 Samuel', 7, 4, '&nbsp;نو بنى اِسرائيلو د بعل او عستارات د بُتانو نه خپل ځانونه خلاص کړل او صِرف د مالِک خُدائ عبادت يې کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6855, '1 Samuel 7:5', '1 Samuel', 7, 5, '&nbsp;بيا سموئيل ټول بنى اِسرائيليان راوغوښتل چې په مصفاه کښې راغونډ شى او ورته يې وفرمائيل، ”زۀ به هلته ستاسو دپاره مالِک خُدائ ته سوال وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6856, '1 Samuel 7:6', '1 Samuel', 7, 6, '&nbsp;نو هغوئ ټول په مصفاه کښې راغونډ شول. هغوئ څۀ اوبۀ راوويستلې او مالِک خُدائ ته يې د يوې نذرانې په توګه توئ کړې او ټوله ورځ يې روژه ونيوله. هغوئ ووئيل، ”مونږ د مالِک خُدائ خِلاف ګناه کړې ده.“ نو سموئيل په مصفاه کښې د بنى اِسرائيلو مشر جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6857, '1 Samuel 7:7', '1 Samuel', 7, 7, '&nbsp;کله چې فلستيان خبر شول چې بنى اِسرائيل په مصفاه کښې راغونډ شوى دى، فلستى بادشاهان د خپلو سړو سره د هغوئ خِلاف جنګ له راووتل. بنى اِسرائيليان د دې نه خبر شول او ويرېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6858, '1 Samuel 7:8', '1 Samuel', 7, 8, '&nbsp;او سموئيل ته يې ووئيل، ”مالِک خُدائ زمونږ خُدائ پاک ته دُعا کول مۀ پرېږده چې مونږ د فلستيانو نه بچ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6859, '1 Samuel 7:9', '1 Samuel', 7, 9, '&nbsp;سموئيل يو داسې ګډُورے حلال کړو چې مور يې رودله او د يوې نذرانې په توګه يې ټول مالِک خُدائ ته وسوزولو. بيا يې مالِک خُدائ ته دُعا وکړه چې د بنى اِسرائيلو مدد وکړى او مالِک خُدائ د هغۀ دُعا واورېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6860, '1 Samuel 7:10', '1 Samuel', 7, 10, '&nbsp;کله چې سموئيل نذرانه پېش کوله، نو فلستيان د حملې دپاره مخکښې ورغلل، خو بيا هم په هغه وخت مالِک خُدائ د هغوئ خِلاف د يو لوئ تندر په شان آواز وکړو. فلستيان دومره په وارخطايۍ آخته شول چې وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6861, '1 Samuel 7:11', '1 Samuel', 7, 11, '&nbsp;بنى اِسرائيليان د مصفاه نه روان شول او تقريباً تر بيت‌کَر پورې په فلستيانو پسې وُو او په لاره باندې يې وژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6862, '1 Samuel 7:12', '1 Samuel', 7, 12, '&nbsp;بيا سموئيل يو کاڼے واخستلو او د مصفاه او شين په مينځ کښې يې ولګولو او وې فرمائيل، ”مالِک خُدائ زمونږ هر قِسم مدد کړے دے.“ او په دې باندې يې ”د مدد کاڼے“ نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6863, '1 Samuel 7:13', '1 Samuel', 7, 13, '&nbsp;نو فلستيانو شکست وخوړو او مالِک خُدائ دې ته پرې نۀ ښودل چې تر کومې پورې سموئيل ژوندے وو چې هغوئ د بنى اِسرائيلو په علاقه قبضه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6864, '1 Samuel 7:14', '1 Samuel', 7, 14, '&nbsp;بنى اِسرائيلو ته هغه ټول ښارونه واپس مِلاو شول چې د عقرون او جات په مينځ کښې وُو او فلستيانو قبضه کړى وُو او داسې بنى اِسرائيلو خپله ټوله علاقه واپس واخستله. او د کنعانيانو او بنى اِسرائيلو په مينځ کښې هم امن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6865, '1 Samuel 7:15', '1 Samuel', 7, 15, '&nbsp;سموئيل ټول عُمر د بنى اِسرائيلو قاضى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6866, '1 Samuel 7:16', '1 Samuel', 7, 16, '&nbsp;هغه به هر کال په بيت‌ايل، جِلجال او مصفاه کښې ګرځېدو او په دې ځايونو کښې يې لانجې هوارولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6867, '1 Samuel 7:17', '1 Samuel', 7, 17, '&nbsp;بيا به هغه واپس په راما کښې خپل کور ته تلو، هلته يې هم د قاضى په توګه خِدمت کولو. هغۀ په راما کښې مالِک خُدائ ته يوه قربان‌ګاه هم جوړه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6868, '1 Samuel 8:1', '1 Samuel', 8, 1, '&nbsp;کله چې سموئيل بوډا شو، هغۀ خپل زامن د بنى اِسرائيلو قاضيان جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6869, '1 Samuel 8:2', '1 Samuel', 8, 2, '&nbsp;د مشر زوئ يې يوايل او د کشر يې ابياه نوم وو، هغوئ په بيرسبع کښې قاضيان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6870, '1 Samuel 8:3', '1 Samuel', 8, 3, '&nbsp;خو هغوئ د خپل پلار په لاره نۀ وُو روان، د هغوئ شوق صِرف پېسې پېدا کول وُو، هغوئ به رشوت اخستو او د اِنصاف تباهى به يې کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6871, '1 Samuel 8:4', '1 Samuel', 8, 4, '&nbsp;نو بيا د بنى اِسرائيلو ټول مشران راغونډ شول او په راما کښې سموئيل له لاړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6872, '1 Samuel 8:5', '1 Samuel', 8, 5, '&nbsp;او هغۀ ته يې ووئيل، ”ګوره، تۀ بوډا کېږې او زامن دې ستا په لاره نۀ دى روان. نو يو بادشاه مقرر کړه چې په مونږ باندې بادشاهى کوى، نو داسې د نورو قومونو په شان به زمونږ هم يو بادشاه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6873, '1 Samuel 8:6', '1 Samuel', 8, 6, '&nbsp;سموئيل د هغوئ بادشاه غوښتلو باندې خوشحاله نۀ وو، نو هغۀ مالِک خُدائ ته سوال وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6874, '1 Samuel 8:7', '1 Samuel', 8, 7, '&nbsp;او مالِک خُدائ ورته وفرمائيل، ”خلق چې درته څۀ هم وائى هغې ته غوږ ونيسه. تۀ هغه څوک نۀ يې چې رد کړے شوے يې، په حقيقت کښې دا زۀ يم چې هغوئ د بادشاه په توګه رد کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6875, '1 Samuel 8:8', '1 Samuel', 8, 8, '&nbsp;چې د کوم وخت نه ما هغوئ د مِصر نه راويستلى دى، نو هغوئ زما نه اوړېدلى دى او د نورو معبودانو عبادت يې کړے دے، او اوس هغوئ تا سره هغه څۀ کوى چې همېشه يې زما سره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6876, '1 Samuel 8:9', '1 Samuel', 8, 9, '&nbsp;نو بيا هغوئ ته غوږ کېږده، خو سخت خبردارے هم ورکړه او هغوئ ته ووايه چې خپل بادشاهان به ورسره څۀ سلوک کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6877, '1 Samuel 8:10', '1 Samuel', 8, 10, '&nbsp;نو سموئيل هغه خلقو ته چا چې بادشاه غوښتو هغه هر څۀ وفرمائيل څۀ چې مالِک خُدائ هغۀ ته فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6878, '1 Samuel 8:11', '1 Samuel', 8, 11, '&nbsp;سموئيل ورته وفرمائيل، ”ستاسو بادشاه به تاسو سره داسې سلوک کوى، هغه به ستاسو زامنو نه فوجيان جوړ کړى، څۀ به د هغۀ د جنګى ګاډو خِدمت کوى، څۀ به د هغۀ د آسونو والا وى او څۀ به د هغۀ د ګاډو نه مخکښې منډې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6879, '1 Samuel 8:12', '1 Samuel', 8, 12, '&nbsp;هغه به ستاسو څۀ زامن د زرګونو سړو او نور د پنځوسو سړو مشران آفسران جوړ کړى. ستاسو زامن به د هغۀ په پټو کښې يوې کوى، د هغۀ فصلونه به رېبى، وسله او د هغۀ د جنګى ګاډو دپاره به نور سامان جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6880, '1 Samuel 8:13', '1 Samuel', 8, 13, '&nbsp;ستاسو لوڼه به دې ته جوړې کړى چې د هغۀ دپاره عطر جوړوى او د هغۀ دپاره به د اخلى پخلى والا او نانبايانو په توګه کار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6881, '1 Samuel 8:14', '1 Samuel', 8, 14, '&nbsp;هغه به ستاسو ښۀ پټى، د انګورو او د زيتُونو باغونه ونيسى او خپلو آفسرانو له به يې ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6882, '1 Samuel 8:15', '1 Samuel', 8, 15, '&nbsp;هغه به د ستاسو د غلې او انګورو لسمه حِصه د خپل دربار د آفسرانو دپاره او د نورو آفسرانو دپاره اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6883, '1 Samuel 8:16', '1 Samuel', 8, 16, '&nbsp;هغه به ستاسو نوکران او ستاسو ښۀ څاروى او خرونه واخلى او کار به ترې نه اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6884, '1 Samuel 8:17', '1 Samuel', 8, 17, '&nbsp;هغه به ستاسو د رَمې لسمه برخه اخلى. او تاسو به په خپله د هغۀ نوکران شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6885, '1 Samuel 8:18', '1 Samuel', 8, 18, '&nbsp;کله چې هغه وخت راشى، نو تاسو به د دې بادشاه نه د خلاصون دپاره فرياد وکړئ، کوم چې تاسو په خپله خوښ کړے وى، خو په هغه وخت کښې به مالِک خُدائ ستاسو شکايتونه نۀ اورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6886, '1 Samuel 8:19', '1 Samuel', 8, 19, '&nbsp;خو خلقو د سموئيل خبره ونۀ منله او وې وئيل، ”نه، مونږ د ځان دپاره يو بادشاه غواړُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6887, '1 Samuel 8:20', '1 Samuel', 8, 20, '&nbsp;نو داسې مونږ به د نورو قومونو په شان شُو، چې په مونږ باندې خپل بادشاه حکومت کوى او په جنګ کښې مو مشرى کوى او زمونږ جنګونه به کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6888, '1 Samuel 8:21', '1 Samuel', 8, 21, '&nbsp;هغوئ چې څۀ هم وئيل نو سموئيل ورته غوږ نيولے وو او بيا لاړو او مالِک خُدائ ته يې وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6889, '1 Samuel 8:22', '1 Samuel', 8, 22, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”هغوئ چې څۀ وائى نو هم هغه شان وکړه او هغوئ له يو بادشاه ورکړه.“ بيا سموئيل د بنى اِسرائيلو ټولو خلقو ته وفرمائيل چې واپس کور ته لاړ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6890, '1 Samuel 9:1', '1 Samuel', 9, 1, '&nbsp;د بنيامين د قبيلې يو مالدار او تکړه سړے وو چې نوم يې قيس وو، هغه د ابى‌اېل زوئ او صرور نمسے وو او د بکورت د خاندان وو، چې د افيخ د قبيلې يوه برخه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6891, '1 Samuel 9:2', '1 Samuel', 9, 2, '&nbsp;د ساؤل په نامه د هغۀ يو زوئ وو چې يو ښائسته زلمے وو. ساؤل په بنى اِسرائيلو کښې د ټولو نه ښائسته سړ‌ے وو او داسې د ټولو نه زيات لوړ هم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6892, '1 Samuel 9:3', '1 Samuel', 9, 3, '&nbsp;د قيس يو څو خرونه ورک شول، نو هغۀ ساؤل ته ووئيل، ”د ځان سره يو نوکر بوځه او هغه خرونه ولټوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6893, '1 Samuel 9:4', '1 Samuel', 9, 4, '&nbsp;هغوئ د اِفرائيم د غرونو په مُلک کښې او سليسه په علاقه کښې وګرځېدل، خو پېدا يې نۀ کړل، هغوئ د سعليم په علاقه کښې ورپسې وګرځېدل، خو خرونه هلته هم نۀ وو. بيا هغوئ د بنيامين په علاقه کښې وګرځېدل، خو بيا يې هم ونۀ موندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6894, '1 Samuel 9:5', '1 Samuel', 9, 5, '&nbsp;کله چې هغوئ د صُوف علاقې ته لاړل، نو ساؤل خپل نوکر ته ووئيل، ”راځه چې واپس کور ته لاړ شُو، کېدے شى زما پلار د خرونو خيال پرېښے وى او زمونږ په حقله پرېشانه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6895, '1 Samuel 9:6', '1 Samuel', 9, 6, '&nbsp;نوکر ورته ووئيل، ”ګوره، په دې ښار کښې د خُدائ پاک يو خِدمتګار دے چې ډېر زيات عزتمند دے ځکه چې هغه څۀ هم وائى نو هغه رښتيا کيږى. راځئ چې هغۀ له ورشو، کېدے شى چې هغه مونږ ته ووائى چې مونږ خرونه چرته موندلے شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6896, '1 Samuel 9:7', '1 Samuel', 9, 7, '&nbsp;ساؤل ترې نه تپوس وکړو، ”کۀ مونږ هغۀ له ورشو، نو مونږ به څۀ ورکوو؟ زمونږ په بوجو کښې خوراک نۀ دے پاتې او زمونږ سره هيڅ هم نشته چې هغۀ له يې ورکړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6897, '1 Samuel 9:8', '1 Samuel', 9, 8, '&nbsp;نوکر ورته په جواب کښې ووئيل، ”زما سره د سپينو زرو يوه وړه سيکه ده. زۀ هغۀ له دا ورکولے شم، نو هغه به مونږ ته ووائى چې مونږ خرونه چرته پېدا کولے شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6898, '1 Samuel 9:14', '1 Samuel', 9, 14, '&nbsp;نو ساؤل او د هغۀ نوکر هغه ښار ته وختل او کله چې هغوئ ورننوتل نو هغوئ سموئيل وليدو چې په لاره باندې د عبادت ځائ ته د هغوئ په طرف راروان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6899, '1 Samuel 9:15', '1 Samuel', 9, 15, '&nbsp;يوه ورځ مخکښې مالِک خُدائ سموئيل ته فرمائيلى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6900, '1 Samuel 9:16', '1 Samuel', 9, 16, '&nbsp;”سبا تقريباً په دې وخت به زۀ د بنيامين د قبيلې يو سړے تا له درولېږم، د هغۀ سر په تېلو غوړ کړه چې هغه زما د خلقو بنى اِسرائيلو بادشاه شى. او هغه به هغوئ د فلستيانو نه خلاص کړى. ما د خپلو خلقو تکليف ليدلے دے او د هغوئ فرياد مې اورېدلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');